const items = $input.all();

const normalizeKey = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const aliases = {
  companyName: ['Company Name', 'Company', 'companyName'],
  jobTitle: ['Job Title', 'Title', 'jobTitle'],
  location: ['Location', 'Locations', 'Location(s)', 'location'],
  jobDescription: ['Job Description', 'Description', 'JD', 'jobDescription'],
  resume: ['My_resume', 'My Resume', 'Resume', 'myResume'],
  status: ['Status', 'status'],
};

const read = (json, names) => {
  const keys = new Map(Object.keys(json).map((key) => [normalizeKey(key), key]));
  for (const name of names) {
    const key = keys.get(normalizeKey(name));
    const value = key ? json[key] : undefined;
    if (value != null && String(value).trim()) return String(value).trim();
  }
  return '';
};

const ready = [];
for (const [index, item] of items.entries()) {
  const json = item.json || {};
  json.sheetRowNumber = json.row_number ?? json.rowNumber ?? index + 2;

  const required = {
    companyName: read(json, aliases.companyName),
    jobTitle: read(json, aliases.jobTitle),
    location: read(json, aliases.location),
    jobDescription: read(json, aliases.jobDescription),
    resume: read(json, aliases.resume),
  };
  const missingFields = Object.entries(required)
    .filter(([, value]) => !value)
    .map(([field]) => field);
  const status = read(json, aliases.status).toLowerCase();

  if (missingFields.length) {
    console.log(`Skipping sheet row ${json.sheetRowNumber}; missing: ${missingFields.join(', ')}`);
    continue;
  }
  if (status) {
    console.log(`Skipping sheet row ${json.sheetRowNumber}; status is "${status}".`);
    continue;
  }

  item.json = json;
  ready.push(item);
}

console.log(`Ready outreach rows: ${ready.length}`);
return ready;

const item = $input.item.json || {};
const keys = Object.keys(item);

// Normalize: keep only letters and digits
const norm = k =>
  (k || '')
    .toString()
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');

const map = {};
for (const k of keys) {
  const nk = norm(k);
  if (!nk) continue;

  // Keep the *first* mapping we see for a normalized key
  if (!Object.prototype.hasOwnProperty.call(map, nk)) {
    map[nk] = k;
  }
}

const read = (aliases = []) => {
  for (const a of aliases) {
    const nk = norm(a);
    const rk = map[nk] || a;
    const v = item[rk];
    if (v != null && v !== '') {
      return String(v).trim();
    }
  }
  return '';
};

const out = {
  sno: read(['SNo', 'S No', 'S_No', 'A', 'sno']),
  companyName: read(['Company Name', 'Company', 'B', 'companyName']),
  jobTitle: read(['Job Title', 'Title', 'C', 'jobTitle']),
  location: read(['Location', 'Locations', 'Location(s)', 'D', ' Location', 'location']),
  jobLink: read(['Job Link', 'Link', 'URL', 'E', 'jobLink']),
  jobDescription: read(['Job Description', 'Description', 'JD', 'F', ' Job Description', 'jobDescription']),
  myResume: read(['My_resume', 'My Resume', 'Resume', 'G', 'myResume']),
  rowNumber: item.sheetRowNumber || item.row_number || item.rowNumber || 2,
  row_number: item.sheetRowNumber || item.row_number || item.rowNumber || 2,
};

console.log(`Row ${out.rowNumber}: ${out.companyName} - ${out.jobTitle}`);
return out;

const companyName = $json.companyName;
const jobTitle = $json.jobTitle;
const location = $json.location;
const jobDescription = $json.jobDescription;
const myResume = $json.myResume;

const departmentKeywords = [
  'Data', 'Analytics', 'Engineering', 'Marketing', 'Sales', 'Product',
  'Finance', 'People', 'Operations', 'Design', 'Security', 'Customer Success'
];
const department = departmentKeywords.find((keyword) =>
  jobTitle.toLowerCase().includes(keyword.toLowerCase())
) || jobTitle.split(/\s+/)[0];

const locationQuery = `("${location}" OR "Remote")`;
const searchQueries = [
  {
    category: 'recruiters',
    searchQuery: `site:linkedin.com/in "${companyName}" ("Recruiter" OR "Talent Acquisition" OR "People Partner" OR "HR Business Partner") ("${department}" OR "${jobTitle}") "Present" ${locationQuery} -jobs -former -previous`,
  },
  {
    category: 'managers',
    searchQuery: `site:linkedin.com/in "${companyName}" ("${department} Manager" OR "Director of ${department}" OR "Head of ${department}" OR "VP ${department}" OR "Hiring Manager") "Present" ${locationQuery} -jobs -former -previous`,
  },
  {
    category: 'employees',
    searchQuery: `site:linkedin.com/in "${companyName}" ("${jobTitle}" OR "Senior ${jobTitle}" OR "Lead ${jobTitle}" OR "${department} Specialist") "Present" ${locationQuery} -jobs -former -previous -Manager -Director`,
  },
];

return searchQueries.map((query, index) => ({
  json: {
    ...query,
    priority: index + 1,
    companyName,
    jobTitle,
    location,
    department,
    jobDescription,
    myResume,
  },
}));

// Parse Google CSE results and preserve the complete job context.
const loopData = $('Search Query Loop').item.json;
let searchResults = [];

if (Array.isArray($json.items)) searchResults = $json.items;

const profiles = searchResults
  .filter((result) => {
    const link = result.link || result.url || '';
    return link.includes('linkedin.com/in/') && !link.includes('/company/') && !link.includes('/jobs/');
  })
  .map((result) => {
    const sourceUrl = result.link || result.url;
    const cleanUrl = sourceUrl.split('?')[0].replace(/\/+$/, '') + '/';
    const title = result.title || '';
    return {
      linkedinUrl: cleanUrl,
      title,
      snippet: result.snippet || result.description || '',
      name: (title.split(' - ')[0] || title.split('|')[0] || '').trim(),
    };
  })
  .slice(0, 15);

return {
  json: {
    category: loopData.category,
    profiles,
    totalFound: profiles.length,
    searchQuery: loopData.searchQuery,
    companyName: loopData.companyName,
    jobTitle: loopData.jobTitle,
    location: loopData.location,
    department: loopData.department,
    jobDescription: loopData.jobDescription,
    myResume: loopData.myResume,
  },
};

const allItems = $input.all();
if (!allItems.length) throw new Error('No search results reached aggregation.');

const first = allItems[0].json;
const grouped = {
  recruiters: [],
  managers: [],
  employees: [],
  metadata: {
    companyName: first.companyName,
    jobTitle: first.jobTitle,
    location: first.location,
    department: first.department,
    jobDescription: first.jobDescription,
    myResume: first.myResume,
    searchTimestamp: new Date().toISOString(),
  },
};

for (const item of allItems) {
  const category = item.json.category;
  if (category in grouped && Array.isArray(item.json.profiles)) {
    grouped[category] = item.json.profiles;
  }
}

return { json: grouped };

const data = $json;
const { companyName, jobTitle, location, department, jobDescription, myResume } = data.metadata;

const prompt = `You rank potential outreach contacts for one job application.

JOB CONTEXT
- Company: ${companyName}
- Role: ${jobTitle}
- Location: ${location}
- Department: ${department}
- Job description: ${jobDescription}
- Candidate resume: ${myResume}

SEARCH CANDIDATES
Recruiters: ${JSON.stringify(data.recruiters)}
Managers: ${JSON.stringify(data.managers)}
Employees: ${JSON.stringify(data.employees)}

TASK
Select up to four contacts per category. Rank only from the supplied search candidates.
- Recruiters: prioritize current company alignment and recruiting relevance to the role.
- Managers: prioritize likely ownership of the role or its department.
- Employees: prioritize role similarity and credible peer relevance.
- Prefer the target location or explicit remote relevance.

GROUNDING RULES
1. Copy every LinkedIn URL exactly from the input.
2. Use only facts visible in the job context or candidate search result.
3. Do not infer current employment, authority, skills, education, or relationships.
4. If fewer than four candidates are supported, return fewer than four.
5. Keep each description to one evidence-based sentence.

Return strict JSON only:
{
  "recruiters": [{"name":"","linkedinUrl":"","title":"","description":""}],
  "managers": [{"name":"","linkedinUrl":"","title":"","description":""}],
  "employees": [{"name":"","linkedinUrl":"","title":"","description":""}]
}`;

return { json: { prompt, profileData: data } };

// 1. Fetch the Job/Resume data from the earlier node
// "Normalize Job Context" must match your node name exactly.
// .first().json gets the data from that node dynamically.
const jobData = $('Normalize Job Context').first().json;

// 2. Fetch the Recruiter/Manager/Employee data from the input
// $input.first().json gets the data coming into this node from "Build Grounded Contact Context"
const emailData = $input.first().json;

// 3. Merge dynamically using the Spread Operator (...)
// This automatically grabs ALL columns/keys from both sources,
// regardless of what the column names are.
const combinedRow = {
  ...jobData,
  ...emailData
};

// 4. Return the merged result
return {
  json: combinedRow
};

/**
 * Gemini → JSON parser + sheet flattener (shape-agnostic).
 * Handles: {role:'model', parts:[{text}]}, {text}, {response}, {candidates[].content.parts[].text}, strings.
 * Keeps descriptions; pads each group to 4; flattens to your headers (linkedln spelling preserved).
 */

//////////////////////
// Helpers
//////////////////////

const asStr = (v) => (v == null ? "" : String(v));
const stripFences = (s) =>
  asStr(s).replace(/^\s*```(?:json)?\s*/i, "").replace(/\s*```\s*$/i, "").trim();

/** Collect candidate text blobs from many possible shapes (shallow + common nests). */
function collectTexts(obj, out) {
  if (!obj) return;
  if (typeof obj === "string") { out.push(obj); return; }
  if (typeof obj !== "object") return;

  // Common direct fields
  if (typeof obj.text === "string") out.push(obj.text);
  if (typeof obj.response === "string") out.push(obj.response);
  if (typeof obj.output === "string") out.push(obj.output);
  if (typeof obj.message === "string") out.push(obj.message);

  // parts[].text
  if (Array.isArray(obj.parts)) {
    for (const p of obj.parts) if (p && typeof p.text === "string") out.push(p.text);
  }

  // candidates[0].content.parts[].text
  if (Array.isArray(obj.candidates) && obj.candidates[0]?.content?.parts) {
    for (const p of obj.candidates[0].content.parts) if (p && typeof p.text === "string") out.push(p.text);
  }

  // a few likely nests
  const likelyKeys = ["content", "data", "result", "message", "output"];
  for (const k of likelyKeys) {
    const v = obj[k];
    if (v && typeof v === "object") collectTexts(v, out);
  }
}

/** Try to parse the first candidate that contains a valid JSON with expected keys. */
function firstValidProfilesJSON(texts) {
  for (const raw of texts) {
    const s = stripFences(raw);
    const start = s.indexOf("{");
    const end   = s.lastIndexOf("}");
    if (start === -1 || end === -1 || end <= start) continue;
    const chunk = s.slice(start, end + 1);
    try {
      const parsed = JSON.parse(chunk);
      if (
        parsed &&
        (Array.isArray(parsed.recruiters) ||
         Array.isArray(parsed.managers)   ||
         Array.isArray(parsed.employees))
      ) {
        return parsed;
      }
    } catch (_) { /* try next */ }
  }
  return null;
}

function toPerson(x, label) {
  return {
    name: asStr(x?.name || label).trim(),
    linkedinUrl: asStr(x?.linkedinUrl).trim(),
    title: asStr(x?.title).trim(),
    description: asStr(x?.description).trim(),
  };
}

function pad(arr, label) {
  const out = Array.isArray(arr) ? arr.map((x, i) => toPerson(x, `${label} ${i + 1}`)) : [];
  while (out.length < 4) out.push(toPerson({}, `${label} ${out.length + 1}`));
  return out.slice(0, 4);
}

//////////////////////
// Parse current input
//////////////////////

// Read ALL incoming items from the Gemini node path
// (This Code node should be directly after the Gemini node.)
const items = $input.all();
if (!items.length) {
  throw new Error("No input items for parser. Ensure this node is connected right after the Gemini node.");
}

// Collect candidate text blobs from all items
const candidateTexts = [];
for (const it of items) collectTexts(it.json, candidateTexts);

// Fallback: stringify first item to give the parser something to try
if (!candidateTexts.length) {
  candidateTexts.push(JSON.stringify(items[0].json ?? {}, null, 2));
}

// Find and parse the first valid JSON with expected keys
const parsed = firstValidProfilesJSON(candidateTexts);
if (!parsed) {
  // log a short preview for debugging
  console.log("DEBUG candidateTexts preview:");
  for (const raw of candidateTexts.slice(0, 3)) {
    console.log(stripFences(raw).slice(0, 400));
  }
  throw new Error("Could not find valid JSON with recruiters/managers/employees in Gemini output.");
}

// Normalize, pad, flatten
const recruiters = pad(parsed.recruiters, "Recruiter");
const managers   = pad(parsed.managers,   "Manager");
const employees  = pad(parsed.employees,  "Employee");

const flat = {};
for (let i = 0; i < 4; i++) {
  // Recruiters (note: linkedln spelling kept)
  flat[`Recruiter${i+1}_name`]                  = recruiters[i].name;
  flat[`Recruiter${i+1}_linkedln_profile_link`] = recruiters[i].linkedinUrl;
  flat[`Recruiter${i+1}_job_title`]             = recruiters[i].title;
  flat[`Recruiter${i+1}_description`]           = recruiters[i].description;

  // Employees
  flat[`Employee${i+1}_name`]                   = employees[i].name;
  flat[`Employee${i+1}_linkedln_link`]          = employees[i].linkedinUrl;
  flat[`Employee${i+1}_job_title`]              = employees[i].title;
  flat[`Employee${i+1}_description`]            = employees[i].description;

  // Managers
  flat[`Manager${i+1}_name`]                    = managers[i].name;
  flat[`Manager${i+1}_linkedln_link`]           = managers[i].linkedinUrl;
  flat[`Manager${i+1}_job_title`]               = managers[i].title;
  flat[`Manager${i+1}_description`]             = managers[i].description;
}

// Keep upstream rowNumber if present
flat.SNo = $('Normalize Job Context').first().json.sno;

// Return one item (flattened) — if you prefer to emit arrays too, add recruiters/managers/employees
return flat;

// Collect all valid LinkedIn URLs from the flattened structure
const item = $input.first().json;
const results = [];

// Helper to add url if exists
const add = (url) => {
  if (url && url.includes('linkedin.com/in')) {
    results.push({
      json: {
        // The specific format Apify wants for the URL
        linkedin: url.trim(),

        // CRITICAL: We keep the original sheet data attached here
        // so we can map the emails back to the correct row later.
        originalData: item 
      }
    });
  }
};

// Loop through 4 of each category
for (let i = 1; i <= 4; i++) {
  add(item[`Recruiter${i}_linkedln_profile_link`]);
  add(item[`Manager${i}_linkedln_link`]);
  add(item[`Employee${i}_linkedln_link`]);
}

// Returns a list (Array) of items. 
// N8N will output multiple items like:
// Item 1: { "linkedin": "...", "originalData": ... }
// Item 2: { "linkedin": "...", "originalData": ... }
return results;

/**
 * n8n Code Node: Normalize Apify Data & Merge with Spreadsheet
 * * Improvements:
 * 1. Robust Email Extraction: Checks 4 different locations in the JSON.
 * 2. Smart Matching: Matches via LinkedIn public identifier (e.g. 'john-doe-123') to avoid URL format mismatches.
 * 3. Context Generation: Creates a pre-formatted 'emailContext' string for Gemini, saving tokens and improving accuracy.
 * 4. Signal Detection: Automatically flags "Leadership", "Technical", or "Open to work" for tone adjustment.
 */

// --- 1. GET INPUTS ---
// Robustly fetch original spreadsheet data (handle different flow structures)
let originalData = {};
try {
    originalData = $('Prepare Profile Enrichment').first().json.originalData;
} catch (e) {
    // Fallback: try to grab it from the current input if passed through directly
    originalData = $input.first().json.originalData || {};
}

// Get Scraper Results from input
const scraperResults = $input.all().map(item => item.json);


// --- 2. HELPER FUNCTIONS ---

const safeStr = (v, fallback = "") => (typeof v === "string" && v.trim()) ? v.trim() : (v ?? fallback ?? "");

// Extract unique ID from LinkedIn URL for robust matching (e.g. "andrew-sus" from "linkedin.com/in/andrew-sus/")
const getID = (url) => {
    if (!url) return '';
    try {
        const clean = url.split('?')[0].replace(/\/+$/, '');
        const parts = clean.split('/in/');
        return parts.length > 1 ? parts[1].toLowerCase() : clean;
    } catch (e) { return ''; }
};

// Normalize experience list for cleaner reading by Gemini
const normalizeExperience = (exp = []) => {
    if (!Array.isArray(exp)) return [];
    return exp.map(e => ({
        title: safeStr(e.title),
        company: safeStr(e.company),
        duration: safeStr(e.duration),
        isCurrent: !!e.is_current,
        // Truncate description to save tokens while keeping context
        description: safeStr(e.description).substring(0, 200) + (e.description?.length > 200 ? "..." : "")
    })).filter(x => x.title || x.company);
};

// Build a clean "Current Role" object
const buildCurrentRole = (basic, expList) => {
    const currentExp = expList.find(e => e.isCurrent) || expList[0] || {};
    return {
        title: safeStr(currentExp.title || basic?.headline),
        company: safeStr(currentExp.company || basic?.current_company),
        duration: safeStr(currentExp.duration),
        location: safeStr(currentExp.location || basic?.location?.full)
    };
};

// Extract "Signals" for email customization (e.g. adjust tone for leaders vs peers)
const extractSignals = (basic, expList) => {
    const signals = [];
    if (basic?.open_to_work) signals.push("Open to work");

    const currentTitle = (expList.find(e => e.isCurrent)?.title || "").toLowerCase();

    if (/recruit|talent|acquisition/i.test(currentTitle)) signals.push("Talent Role");
    if (/engineer|data|dev|tech/i.test(currentTitle)) signals.push("Technical Role");
    if (/director|head|vp|chief/i.test(currentTitle)) signals.push("Leadership");

    // Check for tenure > 1 year roughly based on duration text
    if (expList.length > 0 && (expList[0].duration?.includes("yr") || expList[0].duration?.includes("year"))) {
        signals.push("Long Tenure");
    }

    return signals;
};

// Robustly find email across various Apify actor output formats
const extractEmail = (profile) => {
    // 1. Check root level
    if (profile.email) return profile.email;
    if (profile.personalEmail) return profile.personalEmail;
    if (Array.isArray(profile.emails) && profile.emails.length > 0) return profile.emails[0];

    // 2. Check nested basic_info
    const basic = profile.basic_info || {};
    if (basic.email) return basic.email;

    return '';
};


// --- 3. BUILD LOOKUP MAP ---
const profileMap = {};
scraperResults.forEach(profile => {
    // Check multiple URL fields to find the ID (Apify format varies)
    const url = profile.url || profile.profileUrl || profile.profile_url || profile.basic_info?.profile_url || profile.linkedin || '';
    const id = getID(url);
    if (id) profileMap[id] = profile;
});


// --- 4. MAIN PROCESSING LOOP ---
const richData = {
    recruiters: [],
    managers: [],
    employees: []
};

// Define your categories and spreadsheet prefixes
const categories = [
    { name: 'recruiters', prefix: 'Recruiter', linkKey: 'linkedln_profile_link' },
    { name: 'managers',   prefix: 'Manager',   linkKey: 'linkedln_link' },
    { name: 'employees',  prefix: 'Employee',  linkKey: 'linkedln_link' }
];

categories.forEach(cat => {
    for (let i = 1; i <= 4; i++) {
        const linkCol = `${cat.prefix}${i}_${cat.linkKey}`;
        const emailCol = `${cat.prefix}${i}_email_id`; // Column to store found email

        const targetUrl = originalData[linkCol];
        if (!targetUrl) continue;

        const targetID = getID(targetUrl);
        const match = profileMap[targetID];

        if (match) {
            // Extract Data
            const email = extractEmail(match);
            const basic = match.basic_info || match; // Handle flat vs nested structure
            const expList = normalizeExperience(match.experience || basic.experience);
            const currentRole = buildCurrentRole(basic, expList);
            const signals = extractSignals(basic, expList);

            // A. Update Spreadsheet Object (Result Column)
            originalData[emailCol] = email;

            // B. Build Rich Context for Gemini
            // This string block is formatted for the LLM to read easily
            const emailContext = [
                `Name: ${basic.fullname || basic.name || 'Candidate'}`,
                `Headline: ${safeStr(basic.headline)}`,
                `Current Role: ${currentRole.title} at ${currentRole.company}`,
                `Tenure/Duration: ${currentRole.duration}`,
                `Location: ${currentRole.location}`,
                `Key Signals: ${signals.join(', ')}`,
                `Summary: ${safeStr(basic.about || basic.summary).substring(0, 400)}...`, // Select First Ready Job summary length
                `Recent Experience: ${expList.slice(0,2).map(e => `${e.title} at ${e.company} (${e.duration})`).join(' | ')}`
            ].join('\n');

            // Add to richData for the next node
            richData[cat.name].push({
                id: `${cat.prefix}${i}`,
                name: basic.fullname || basic.name,
                firstName: basic.first_name || basic.firstName || 'there',
                email: email,
                signals: signals,
                emailContext: emailContext // Pass this pre-formatted string to Gemini
            });
        }
    }
});

// --- 5. RETURN OUTPUT ---
return {
    json: {
        ...originalData,
        richData: richData
    }
};

