const originalData = $('Build Grounded Contact Context').first().json;
const response = $input.first().json;
const rawText =
  response?.content?.parts?.[0]?.text ??
  response?.candidates?.[0]?.content?.parts?.[0]?.text ??
  response?.text ??
  response?.response;

if (typeof rawText !== 'string' || !rawText.trim()) {
  throw new Error('Recruiter drafting returned no text.');
}

let drafts;
try {
  const fence = String.fromCharCode(96).repeat(3);
  const cleanJson = rawText.replace(fence + 'json', '').replaceAll(fence, '').trim();
  drafts = JSON.parse(cleanJson);
} catch (error) {
  throw new Error('Recruiter drafting returned invalid JSON: ' + error.message);
}

for (let index = 1; index <= 4; index += 1) {
  const key = 'Recruiter' + index;
  const subject = String(drafts[key]?.subject || '').trim();
  const body = String(drafts[key]?.body || '').trim();
  if (!subject || !body) continue;
  originalData[key + '_email'] = 'Subject: ' + subject + '\n\n' + body;
  originalData[key + '_draft_subject'] = subject;
  originalData[key + '_draft_body'] = body;
}

originalData.row_number = $('Merge Job and Contact Context').first().json.rowNumber;
originalData.Status = 'In Progress';
return { json: originalData };

const data = $input.first().json;
const items = [];
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

for (let index = 1; index <= 4; index += 1) {
  const prefix = 'Recruiter' + index;
  const recipientEmail = String(data[prefix + '_email_id'] || '').trim();
  const subject = String(data[prefix + '_draft_subject'] || '').trim();
  const body = String(data[prefix + '_draft_body'] || '').trim();
  if (!emailPattern.test(recipientEmail) || !subject || !body) continue;
  items.push({
    json: {
      recipientEmail,
      subject,
      body,
      name: data[prefix + '_name'] || '',
      category: 'Recruiter',
    },
  });
}

return items;

